const body = $input.first().json;
if (body.errors?.length || !body.data?.fields || !Array.isArray(body.data.values)) throw new Error('Aura 概念查詢失敗，請檢查連線或執行紀錄。');
const metric=m=>({metricCode:m.metricCode,name:m.name,definition:m.definition,status:m.status});
const products=body.data.values.map(row=>{
 const p=Object.fromEntries(body.data.fields.map((key,i)=>[key,row[i]]));
 return {productCode:p.productCode,productName:p.productName,definition:p.definition,status:p.status,aumStatus:p.aumStatus,incomeStatus:p.incomeStatus,aumMetrics:(p.aumMetrics||[]).map(metric),incomeMetrics:(p.incomeMetrics||[]).map(metric)};
});
if (!products.length) throw new Error('Aura 概念圖沒有候選產品，請確認部署。');
const request=$('KB Input').first().json;
return [{json:{question:request.question,domains:request.domains,products}}];

