const body=$input.first().json;
if(body.errors?.length||!body.data?.fields||!Array.isArray(body.data.values)) throw new Error('Aura 映射查詢失敗，請檢查連線或執行紀錄。');
const choice=$('Jev - Select Products').first().json.output;
const catalog=$('Concept Catalog').first().json.products;
const rows=body.data.values.map(row=>Object.fromEntries(body.data.fields.map((k,i)=>[k,row[i]])));
const messages=[choice.message];
const products=choice.selections.filter((s,i,a)=>a.findIndex(x=>x.productCode===s.productCode&&x.domain===s.domain)===i).map(s=>{
 const concept=catalog.find(p=>p.productCode===s.productCode);
 const found=rows.find(p=>p.productCode===s.productCode&&p.domain===s.domain);
 if(!found) messages.push(concept.productName+'（'+s.domain+'）未找到映射。');
 if(['pending_confirmation','overlap_unresolved','draft'].includes(concept[s.domain+'Status'])) messages.push(concept.productName+'（'+s.domain+'）：'+concept.definition);
 const metrics=concept[s.domain+'Metrics'];
 for(const metric of metrics) if(['pending_confirmation','overlap_unresolved','draft'].includes(metric.status)) messages.push(metric.name+'：'+metric.definition);
 if(found?.mappings.some(m=>m.lineageStatus==='missing_evidence')) messages.push(concept.productName+'有映射缺少完整底表血緣。');
 return {productCode:s.productCode,productName:concept.productName,domain:s.domain,definition:concept.definition,definitionStatus:concept[s.domain+'Status'],metrics,mappingStatus:found?.status||'mapping_missing',mappings:found?.mappings||[]};
});
return [{json:{products,message:[...new Set(messages.filter(Boolean))].join('\n')}}];
